Here is the complete implementation of the `<x-details>` web component using the Shadow DOM.

I have implemented this as a single file solution containing HTML, CSS, and JavaScript so you can copy-paste it directly to test it.

### Features Included:
1.  **Shadow DOM encapsulation**: Styles and logic are isolated.
2.  **Toggle Logic**: Uses `checked` state to track expansion.
3.  **Visuals**:
    *   Square icon with `+` or `-`.
    *   Header with bottom border and larger font.
    *   "Expand more" button appears when collapsed.
4.  **Slots**: Accepts `header`, `intro`, and `details`.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>X-Details Component</title>
    <style>
        /* Base styles for demonstration */
        body {
            font-family: sans-serif;
            padding: 50px;
            background-color: #f4f4f9;
        }

        /* --- COMPONENT STYLES (Scoped via Shadow DOM) --- */

        :host {
            display: block;
            width: 100%;
            max-width: 600px;
            margin-bottom: 20px;
            box-sizing: border-box;
        }

        .xd-container {
            position: relative;
            border: 1px solid #ccc;
            border-radius: 4px;
            overflow: hidden;
            background: white;
        }

        /* The Trigger Row (Icon + Header) */
        .xd-trigger {
            display: flex;
            align-items: center;
            justify-content: space-between;
            cursor: pointer;
            user-select: none;
            transition: background-color 0.2s;
        }

        .xd-trigger:hover {
            background-color: #fafafa;
        }

        /* The Square Icon */
        .xd-icon {
            width: 24px;
            height: 24px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #555;
            font-weight: bold;
            font-size: 18px;
            flex-shrink: 0;
        }

        /* The Header Text */
        .xd-header-text {
            font-size: 1.1em; /* Slightly larger font */
            font-weight: 600;
            padding: 12px 16px;
            border-bottom: 1px solid #ddd;
            outline: none;
        }

        /* The Button inside the trigger */
        .xd-btn {
            padding: 8px 16px;
            background-color: transparent;
            border: 1px solid #ccc;
            border-radius: 4px;
            cursor: pointer;
            font-size: 0.9em;
            color: #555;
            transition: all 0.2s;
        }

        .xd-btn:hover {
            background-color: #eee;
        }

        /* The Content Area */
        .xd-content {
            display: none; /* Hidden by default */
            padding: 0 16px;
        }

        /* Intro Part (Always visible when expanded) */
        .xd-intro {
            padding: 16px 0;
            border-bottom: 1px solid #eee;
            color: #666;
            line-height: 1.5;
        }

        /* Details Part (Visible only when expanded) */
        .xd-details {
            padding: 16px 0;
            color: #333;
        }

        /* State: Expanded */
        .xd-container[open] .xd-content {
            display: block;
        }

        /* Adjust header style slightly when expanded? Optional. 
           Here we keep the border consistent. */
    </style>
</head>
<body>

    <!-- Usage Example -->
    <x-details>
        <span slot="header">Advanced Configuration</span>
        <div slot="intro">This section is always visible when the component is open. It serves as a summary or context.</div>
        <div slot="details">
            <p>This is the actual detailed information that expands.</p>
            <ul>
                <li>Option A</li>
                <li>Option B</li>
                <li>Option C</li>
            </ul>
        </div>
    </x-details>

    <!-- More examples -->
    <x-details>
        <span slot="header">About Us</span>
        <div slot="intro">We are a team dedicated to building great software.</div>
        <div slot="details">Founded in 2023, our mission is to simplify complex problems...</div>
    </x-details>

    <script type="module">
        class XDetails extends HTMLElement {
            constructor() {
                super();
                this.attachShadow({ mode: 'open' });

                // Store slots
                this.header = this.querySelector('[slot="header"]');
                this.intro = this.querySelector('[slot="intro"]');
                this.details = this.querySelector('[slot="details"]');
            }

            connectedCallback() {
                this.render();
                this.setupEventListeners();
            }

            render() {
                this.shadowRoot.innerHTML = `
                    <style>
                        ${this.getStyles()}
                    </style>

                    <div class="xd-container">
                        <div class="xd-trigger" @click=${(e) => this.toggle(e)}>
                            <div class="xd-icon">${this.getState()}</div>
                            <div class="xd-header-text">${this.getHeaderContent()}</div>
                            <button class="xd-btn" @click=${(e) => this.toggle(e)}>${this.getButtonText()}</button>
                        </div>

                        <div class="xd-content">
                            ${this.getIntroContent()}
                            ${this.getDetailsContent()}
                        </div>
                    </div>
                `;
            }

            getStyles() {
                return `
                    :host {
                        display: block;
                        width: 100%;
                        max-width: 600px;
                        margin-bottom: 20px;
                        box-sizing: border-box;
                    }
                    .xd-container {
                        position: relative;
                        border: 1px solid #ccc;
                        border-radius: 4px;
                        overflow: hidden;
                        background: white;
                    }
                    .xd-trigger {
                        display: flex;
                        align-items: center;
                        justify-content: space-between;
                        cursor: pointer;
                        user-select: none;
                        transition: background-color 0.2s;
                    }
                    .xd-trigger:hover {
                        background-color: #fafafa;
                    }
                    .xd-icon {
                        width: 24px;
                        height: 24px;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        color: #555;
                        font-weight: bold;
                        font-size: 18px;
                        flex-shrink: 0;
                    }
                    .xd-header-text {
                        font-size: 1.1em;
                        font-weight: 600;
                        padding: 12px 16px;
                        border-bottom: 1px solid #ddd;
                        outline: none;
                    }
                    .xd-btn {
                        padding: 8px 16px;
                        background-color: transparent;
                        border: 1px solid #ccc;
                        border-radius: 4px;
                        cursor: pointer;
                        font-size: 0.9em;
                        color: #555;
                        transition: all 0.2s;
                    }
                    .xd-btn:hover {
                        background-color: #eee;
                    }
                    .xd-content {
                        display: none;
                        padding: 0 16px;
                    }
                    .xd-intro {
                        padding: 16px 0;
                        border-bottom: 1px solid #eee;
                        color: #666;
                        line-height: 1.5;
                    }
                    .xd-details {
                        padding: 16px 0;
                        color: #333;
                    }
                    .xd-container[open] .xd-content {
                        display: block;
                    }
                `;
            }

            setupEventListeners() {
                // Click on the whole container to toggle
                this.shadowRoot.addEventListener('click', (e) => {
                    const target = e.target;

                    // If clicked on the main trigger area OR the button, toggle
                    if (target.closest('.xd-trigger') || target.classList.contains('xd-btn')) {
                        this.toggle(e);
                    }
                });
            }

            toggle(event) {
                event.stopPropagation(); // Prevent bubbling if needed

                const isOpen = this.hasAttribute('open');
                this.setAttribute('open', !isOpen);

                // Optional: Add animation class here if desired
            }

            getState() {
                const isOpen = this.hasAttribute('open');
                return isOpen ? '-' : '+';
            }

            getButtonText() {
                const isOpen = this.hasAttribute('open');
                return isOpen ? 'Collapse' : 'Expand more';
            }

            getHeaderContent() {
                return this.header ? this.header.textContent.trim() : '';
            }

            getIntroContent() {
                return this.intro ? this.intro.outerHTML : '';
            }

            getDetailsContent() {
                return this.details ? this.details.outerHTML : '';
            }
        }

        customElements.define('x-details', XDetails);
    </script>
</body>
</html>
```

